// Given: demo 2 (Module 2). Do not edit this file.
// Your World steps a few bodies; the dashed boxes are the AABBs from your gather().
// Watch the spinning plank's AABB grow and shrink as it turns.
import { World } from "../world/world";
import { clear, drawAABB, drawBody, drawMessage } from "../render/debugDraw";
import { startLoop } from "../render/loop";
import { createView } from "../render/view";
import { bindKeys } from "./demo1";
import { mountCanvas, todoBox } from "./ui";
import type { Demo } from "./types";

export const demo2: Demo = {
  title: "Demo 2: the world and its AABBs",
  description:
    "Your Exercise 2 World with gravity turned off, so you can watch rotating bodies' AABBs change. Space pauses, S steps once.",
  mount(container) {
    try {
      const world = new World({ gravity: { x: 0, y: 0 } });
      world.addBody({
        shape: { kind: "box", halfWidth: 2, halfHeight: 0.2 },
        position: { x: -2.5, y: 0 },
        mass: 1,
        angularVelocity: 0.8,
      });
      world.addBody({
        shape: { kind: "box", halfWidth: 0.7, halfHeight: 0.7 },
        position: { x: 2.5, y: 1 },
        mass: 1,
        angularVelocity: -1.5,
      });
      world.addBody({
        shape: { kind: "circle", radius: 0.6 },
        position: { x: 2.5, y: -1.5 },
        mass: 1,
        angularVelocity: 3,
      });
      world.addBody({
        shape: { kind: "plane", normal: { x: 0, y: 1 }, offset: -3 },
        position: { x: 0, y: 0 },
        mass: 0,
      });
      const view = createView(mountCanvas(container, 360), {
        center: { x: 0, y: 0 },
        pixelsPerMetre: 45,
      });
      const loop = startLoop({
        step: (dt) => world.step(dt),
        render: () => {
          clear(view);
          for (const g of world.gather()) {
            drawAABB(view, g.aabb);
            drawBody(view, g.body);
          }
          drawMessage(
            view,
            `${world.bodies.length} bodies (the plane's AABB is infinite, so it is not drawn)`,
          );
        },
      });
      const unbind = bindKeys(loop);
      return () => {
        unbind();
        loop.stop();
      };
    } catch (e) {
      container.appendChild(todoBox(e));
      return () => {};
    }
  },
};
